// lib/surfEngine.js
export function calculateSurfScore({ waveHeight, wavePeriod, windSpeed, tide }) {
    let score = 0;

    // Wave height (meters)
    if (waveHeight > 1 && waveHeight < 2.5) score += 35;
    else if (waveHeight >= 2.5) score += 25;

    // Period
    if (wavePeriod > 10) score += 35;
    else if (wavePeriod > 7) score += 20;

    // Wind penalty
    if (windSpeed < 8) score += 30;
    else if (windSpeed < 15) score += 15;

    // Tide influence
    score *= tide?.factor ?? 1;

    return Math.min(100, Math.round(score));
}

// Simple surf interpretation
export function surfLabel(score) {
    if (score > 80) return "🔥 Epic";
    if (score > 60) return "👍 Good";
    if (score > 40) return "🌊 Ok";
    return "💨 Poor";
}